/* ---------- Attachment tray ---------- */
/* a drop zone, then the files as plain rows. Each file wears its type's hue: its badge, its ring and the wash that fills its
   row from the left as it uploads. Once it is up the agent reads it (the line shimmers) and says what it found, like 12 pages */
.atx{display:flex;flex-direction:column;gap:10px}
/* its motion (the core's motion pieces, owner, 26 Nov): a press on a file's remove button shows at once (.mx-press), and in
   Clean the card grows with its files on the spring (.mx-grow) */
.atx-drop{display:flex;flex-direction:column;align-items:center;gap:6px;padding:26px var(--dm-s-4);border-radius:var(--dm-r-card);background:none;cursor:pointer;position:relative;font-size:13.5px;transition:background .35s,box-shadow .35s,transform .45s var(--dm-ease)}
/* the dashed edge is drawn in SVG so its dashes can march around the corners: drifting slowly at rest, taking the accent
   under the pointer, and marching faster while a file is dragged over */
.atx-ants{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.atx-ants rect{fill:none;stroke:var(--dm-faint);stroke-width:1.5;stroke-linecap:round;stroke-dasharray:4.5px var(--dm-ag,6.5px);transition:stroke .35s}
@keyframes atxants{to{stroke-dashoffset:calc(var(--dm-ap,11px) * -1)}}
.atx-drop.over{background:var(--dm-accent-bg)}
@media (hover:hover) and (pointer:fine){.atx-drop:hover{background:var(--dm-accent-bg)}}
.atx-drop.over .atx-ants rect{stroke:var(--dm-accent-mark,var(--dm-accent))}
@media (hover:hover) and (pointer:fine){.atx-drop:hover .atx-ants rect{stroke:var(--dm-accent-mark,var(--dm-accent))}}
.atx-ants rect{animation:atxants 2.6s linear infinite}
.atx-drop.over .atx-ants rect{animation-duration:.9s}
.atx-drop.over{transform:scale(1.015)}
.atx-file{position:absolute;inset:0;opacity:0;cursor:pointer}
/* the file input is clear over the drop zone, so the zone shows its focus */
.atx-drop:has(.atx-file:focus-visible){outline:2px solid var(--dm-focus);outline-offset:2px}
.atx-ic{position:relative;width:34px;height:34px;border-radius:calc(11px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow);display:grid;place-items:center;color:var(--dm-fg2);transition:transform .45s var(--dm-ease),background .35s,color .35s}
.atx-drop.over .atx-ic{transform:translateY(-3px);background:var(--dm-surface);color:var(--dm-accent-fg,var(--dm-accent))}
@media (hover:hover) and (pointer:fine){.atx-drop:hover .atx-ic{transform:translateY(-3px);background:var(--dm-surface);color:var(--dm-accent-fg,var(--dm-accent))}}
/* while a file is over the zone its arrow bobs, and rings spread from the badge */
.atx-drop.over .atx-ic .i{animation:atxbob .9s var(--dm-ease-io) infinite}
@keyframes atxbob{50%{transform:translateY(-2px)}}
.atx-ic::before,.atx-ic::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent));opacity:0;pointer-events:none}
.atx-drop.over .atx-ic::before{animation:atxring 1.4s var(--dm-ease) infinite}
.atx-drop.over .atx-ic::after{animation:atxring 1.4s var(--dm-ease) .7s infinite}
@keyframes atxring{from{opacity:.5;transform:scale(1)}to{opacity:0;transform:scale(1.9)}}
.atx-sample{color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;position:relative;z-index:1}
.atx-list{display:flex;flex-direction:column;gap:2px}
.atx-it{--dm-p:0%;position:relative;display:flex;align-items:center;gap:10px;padding:var(--dm-s-2) 6px var(--dm-s-2) var(--dm-s-2);border-radius:var(--dm-r-in);overflow:hidden;background:linear-gradient(90deg,color-mix(in srgb,var(--dm-c,var(--dm-accent)) 8%,transparent) calc(var(--dm-p) - 24px),color-mix(in srgb,var(--dm-c,var(--dm-accent)) 16%,transparent) calc(var(--dm-p) - 1px),transparent var(--dm-p)) no-repeat}
/* the wash fades once the file is up */
.atx-it.up{background-size:0 100%;transition:background-size .6s var(--dm-ease) .2s}
.atx-ti{width:30px;height:30px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;font-size:9.5px;font-weight:500;letter-spacing:.02em;color:var(--dm-c);background:var(--dm-cb)}
.atx-n{flex:1;min-width:0;font-size:13px}
.atx-nm{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atx-m{display:block;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.atx-m .shim{font-size:inherit}
/* on the wash, the line steps up a grey so it keeps its contrast */
.atx-it:not(.up) .atx-m{color:var(--dm-fg2)}
.atx-ring{width:22px;height:22px;flex:none}
.atx-ring circle{transition:stroke-dashoffset .3s linear}
.atx-ok{display:grid;place-items:center;width:22px;flex:none;color:var(--dm-ok)}
.atx-ok .i{animation:atxpop .45s var(--dm-ease) backwards}
@keyframes atxpop{0%{transform:scale(.4);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:none}}
.atx-rd{display:grid;place-items:center;width:22px;flex:none;color:var(--dm-c)}
.atx-rd .spin{width:12px;height:12px}
/* (a file's remove button is a 28px icon button, as most icon buttons in a row are) */
.atx-it .ib{width:28px;height:28px;flex:none}
.atx-sum{font-size:12.5px;text-align:center;min-height:18px}
:root:not([data-style="soft"],[data-style="clean"]) .atx-it:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:linear-gradient(var(--dm-c,var(--dm-accent)),var(--dm-c,var(--dm-accent))) 0 100%/var(--dm-p) 2px no-repeat}
:root:not([data-style="soft"],[data-style="clean"]) .atx-it.up:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background-size:0 2px}
:root:not([data-style="soft"],[data-style="clean"]) .atx-drop.over .atx-ic:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{animation:atxringbp 1s steps(4,end) infinite}
:root:not([data-style="soft"],[data-style="clean"]) .atx-drop.over .atx-ic:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::after{animation:none}
@keyframes atxringbp{from{opacity:.6;transform:scale(1)}to{opacity:0;transform:scale(1.6)}}
:root:not([data-style="soft"],[data-style="clean"]) .atx-ok .i:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:none}
/* Clean (owner, 18 Nov): one card that grows as files arrive (grow()), its content 16px from each edge, and the whole card is
   the drop target: a file dragged over it fills it with the row grey and draws a dashed hairline 8px in from its edge. Empty,
   it shows Clean's empty state (.atx-em): a small sketch of a file list on a white card, the title, one muted line with a
   browse link, and Add sample files. Files are rows with hairline dividers under their text: one neutral grey circle with the
   type's letters for every file (owner, 18 Nov: one colour, not a hue per type), and while a file uploads its divider becomes
   a rail that fills with ink, the same for every file, a soft sheen running along
   it while the agent reads, then fades as a green tick draws itself. Once there are files, the off-white foot strip (.atx-ft)
   says what the agent can read, its count rolling as each file is read, and holds Add files 16px from the card's side and
   bottom and from the strip's hairline (owner, 23 Nov) */
/* (the dashed hairline is an outline drawn 8px inside the card, so it follows the card's corners) */
:root[data-style="clean"] .atx,:root [data-style="clean"] .atx,:root [data-style="clean"].atx{position:relative;gap:0;background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);overflow:clip;outline:1px dashed transparent;outline-offset:-9px;transition:height .55s cubic-bezier(.22,1,.36,1),background-color var(--dm-t-fast) var(--dm-ease),outline-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .atx.over,:root [data-style="clean"] .atx.over,:root [data-style="clean"].atx.over{background:var(--dm-row);outline-color:var(--dm-faint)}
/* the empty state, the lab's (lab/clean): the sketch is a white card with a hairline and three rows, each a square and a bar,
   fading downward; under it the title, one grey line and a secondary button */
.atx-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:16px;text-align:center}
.atx-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.atx-em>span:not(.atx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.atx-em .pill{margin-top:12px}
.atx-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.atx-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:3px;background:var(--dm-ghost);box-shadow:0 16px 0 var(--dm-ghost),0 32px 0 var(--dm-ghost-2)}
.atx-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost);box-shadow:0 16px 0 var(--dm-ghost),0 32px 0 var(--dm-ghost-2)}
/* the browse link wraps a clear file input, so it opens the file dialog and shows the keyboard's focus */
.atx-br{position:relative;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;cursor:pointer}
@media (hover:hover) and (pointer:fine){.atx-br:hover{text-decoration:underline;text-underline-offset:2px}}
.atx-br:has(.atx-file:focus-visible),.atx-add:has(:focus-visible){outline:2px solid var(--dm-focus);outline-offset:2px}
.atx-br:has(.atx-file:focus-visible){border-radius:4px}
/* the empty state shows until the first file lands, and the foot strip from then on */
.atx-list:not(:empty)~.atx-em,.atx-list:empty~.atx-ft{display:none}
/* (on a phone the count can take two lines: the strip grows with it and Add files stays 16px from the corner) */
.atx-ft{display:flex;align-items:flex-end;gap:12px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
.atx-add{position:relative;overflow:hidden;flex:none;margin-left:auto;cursor:pointer}
:root[data-style="clean"] .atx-list,:root [data-style="clean"] .atx-list,:root [data-style="clean"].atx-list{gap:0;padding:0 16px}
:root[data-style="clean"] .atx-list:not(:empty),:root [data-style="clean"] .atx-list:not(:empty),:root [data-style="clean"].atx-list:not(:empty){padding-block:6px}
/* while the last file is still going up its rail is the lowest thing in the list, so the list keeps 16px under it before the
   foot strip (owner, 18 Nov); once it is read its rail goes, and its words are the lowest, 16px from the strip as they are */
:root[data-style="clean"] .atx-list:has(>.atx-it:last-child :is(.atx-ring,.atx-rd)),:root [data-style="clean"] .atx-list:has(>.atx-it:last-child :is(.atx-ring,.atx-rd)),:root [data-style="clean"].atx-list:has(>.atx-it:last-child :is(.atx-ring,.atx-rd)){padding-bottom:16px}
:root[data-style="clean"] .atx-it,:root [data-style="clean"] .atx-it,:root [data-style="clean"].atx-it{gap:12px;padding:10px 0;border-radius:0;overflow:visible;background:none}
:root[data-style="clean"] .atx-it.up,:root [data-style="clean"] .atx-it.up,:root [data-style="clean"].atx-it.up{background:none}
/* the divider under a row's text (.atx-ln, Clean's own), which is the upload's rail while the file goes up, its ink fill
   clipped to the progress with a soft sheen running along it; a file that is read keeps the hairline, the last one none */
.atx-ln{position:absolute;left:44px;right:0;bottom:0;height:1px;border-radius:999px;background:var(--dm-line);pointer-events:none;transition:height var(--dm-t) var(--dm-ease),background-color var(--dm-t) var(--dm-ease)}
.atx-it:last-child .atx-ln{background:transparent}
.atx-it:not(:has(.atx-ok)) .atx-ln{height:2px;background:var(--dm-rail)}
.atx-ln i{position:absolute;inset:0;border-radius:inherit;background:linear-gradient(90deg,var(--dm-fg) 40%,color-mix(in srgb,var(--dm-fg) 35%,var(--dm-surface)) 50%,var(--dm-fg) 60%) 0 0/250% 100%;clip-path:inset(0 calc(100% - var(--dm-p)) 0 0 round 999px);transition:clip-path .2s linear,opacity .4s var(--dm-ease);animation:atxsheen 1.6s linear infinite}
.atx-it:has(.atx-ok) .atx-ln i{opacity:0;animation:none}
@keyframes atxsheen{from{background-position:100% 0}to{background-position:0 0}}
:root[data-style="clean"] .atx-ti,:root [data-style="clean"] .atx-ti,:root [data-style="clean"].atx-ti{position:relative;width:32px;height:32px;border-radius:50%;font-size:9.5px;color:var(--dm-fg2);background:var(--dm-chip)}
:root[data-style="clean"] .atx-it .atx-m,:root [data-style="clean"] .atx-it .atx-m,:root [data-style="clean"].atx-it .atx-m,:root[data-style="clean"] .atx-it:not(.up) .atx-m,:root [data-style="clean"] .atx-it:not(.up) .atx-m,:root [data-style="clean"].atx-it:not(.up) .atx-m{color:var(--dm-muted)}
/* the upload's own ring stays for screen readers; the rail shows the progress */
:root[data-style="clean"] .atx-ring,:root [data-style="clean"] .atx-ring,:root [data-style="clean"].atx-ring{opacity:0}
:root[data-style="clean"] .atx-rd,:root [data-style="clean"] .atx-rd,:root [data-style="clean"].atx-rd{color:var(--dm-muted)}
/* read: a green disc lands and its tick draws itself */
.atx-okc{display:grid;place-items:center;width:16px;height:16px;border-radius:50%;background:var(--dm-ok-mark);color:var(--dm-surface);animation:atxokin .32s var(--dm-ease) backwards}
.atx-okc svg{width:10px;height:10px;fill:none;stroke:currentColor;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.atx-okc path{stroke-dasharray:1;stroke-dashoffset:1;animation:atxokdraw .34s var(--dm-ease) .16s forwards}
@keyframes atxokin{from{opacity:0;transform:scale(.5)}}
@keyframes atxokdraw{to{stroke-dashoffset:0}}
/* the remove button sits on the content's 16px edge, where the dividers end */
:root[data-style="clean"] .atx-it .ib,:root [data-style="clean"] .atx-it .ib,:root [data-style="clean"].atx-it .ib{width:28px;height:28px}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .atx-it .ib:hover,:root [data-style="clean"] .atx-it .ib:hover,:root [data-style="clean"].atx-it .ib:hover{background:var(--dm-row);color:var(--dm-fg)}}
/* in the foot strip: what the agent can read now, its count rolling up as each file is read. The tick and the words belong
   together (owner, 18 Nov): the tick on the content's edge, 8px, then the words */
:root[data-style="clean"] .atx-sum,:root [data-style="clean"] .atx-sum,:root [data-style="clean"].atx-sum{display:flex;align-items:center;gap:8px;flex:1;min-width:0;min-height:0;padding:5px 0;font-size:12.5px;line-height:18px;text-align:left;color:var(--dm-fg2)}
:root[data-style="clean"] .atx-sum:empty,:root [data-style="clean"] .atx-sum:empty,:root [data-style="clean"].atx-sum:empty{display:none}
/* (a step of --dm-ok in the vivid green keeps the small tick at 3:1 on the off-white strip) */
:root[data-style="clean"] .atx-tk,:root [data-style="clean"] .atx-tk,:root [data-style="clean"].atx-tk{display:grid;place-items:center;flex:none;color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .atx-tk .i,:root [data-style="clean"] .atx-tk .i,:root [data-style="clean"].atx-tk .i{stroke-width:2.2}
.atx-roll{display:inline-grid;overflow:hidden;height:1lh;vertical-align:top}
.atx-roll i{font-style:normal}
.atx-roll i.in{animation:atxroll .32s var(--dm-ease) both}
@keyframes atxroll{from{opacity:0;transform:translateY(60%)}}
@media (prefers-reduced-motion:reduce){.atx-ln i,.atx-okc,.atx-roll i.in{animation:none}.atx-okc path{animation:none;stroke-dashoffset:0}.atx-ln,:root[data-style="clean"] .atx,:root [data-style="clean"] .atx,:root [data-style="clean"].atx{transition:none}}

DM.def('attachment-tray', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{upload}', I('upload'));
  const tray = $('.atx', r), list = $('.atx-list', r), sum = $('.atx-sum', r);
  // Clean: the whole card is the drop target. The drop zone gives way to the empty state (after the list, so it shows only
  // while the list is empty), and the closing line moves into a foot strip with Add files, shown once there are files. The
  // card grows with its files (grow()); Soft and Blueprint as they were
  const clean = (r.closest('[data-style]') || document.documentElement).dataset.style === 'clean';
  if (clean){
    $('.atx-drop', r).remove();
    list.after(html(`<div class="atx-em"><span class="atx-em-art" aria-hidden="true"></span><b>Drop files here</b><span>or <label class="atx-br">browse your files<input type="file" multiple class="atx-file" aria-label="Choose files" title=""></label></span><button type="button" class="pill line sm atx-smp">${I('plus','xs')}Add sample files</button></div>`));
    const ft = html(`<div class="atx-ft"><label class="pill line sm atx-add">${I('plus','xs')}Add files<input type="file" multiple class="atx-file" aria-label="Add files" title=""></label></div>`);
    sum.replaceWith(ft); ft.prepend(sum);
    c.offs.push(grow(tray));
  }
  const drop = clean ? tray : $('.atx-drop', r);
  const kind = n => { const e = (n.split('.').pop() || '').toLowerCase(); return e === 'pdf' ? ['PDF','var(--dm-pr)','var(--dm-pr-bg)'] : /png|jpg|jpeg|gif|webp|fig/.test(e) ? [e.toUpperCase().slice(0,3),'var(--dm-pl)','var(--dm-pl-bg)'] : /csv|xlsx/.test(e) ? ['CSV','var(--dm-pm)','var(--dm-pm-bg)'] : [e.toUpperCase().slice(0,3) || 'TXT','var(--dm-pb)','var(--dm-pb-bg)']; };
  const size = b => b > 1e6 ? (b / 1e6).toFixed(1) + ' MB' : Math.max(1, Math.round(b / 1e3)) + ' KB';
  const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;');
  let read = 0;
  // a file uploads (its row fills with its hue and its ring closes), then the agent reads it and says what it found
  function add(name, bytes, i = 0, found){
    const k = kind(name), sz = size(bytes);
    const it = html(`<div class="atx-it" style="--dm-c:${k[1]};--dm-cb:${k[2]}"><span class="atx-ti">${k[0]}</span><span class="atx-n"><span class="atx-nm">${esc(name)}</span><span class="atx-m"><span>${sz} · <span class="num pc">0%</span></span></span></span><svg class="atx-ring" viewBox="0 0 22 22" role="progressbar" aria-label="Uploading ${esc(name).replace(/"/g, '&quot;')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><circle cx="11" cy="11" r="8" fill="none" stroke="var(--dm-line)" stroke-width="2"/><circle cx="11" cy="11" r="8" fill="none" stroke="${k[1]}" stroke-width="2" stroke-linecap="round" stroke-dasharray="50.3" stroke-dashoffset="50.3" transform="rotate(-90 11 11)"/></svg><button class="ib mx-press" aria-label="Remove ${esc(name).replace(/"/g, '&quot;')}" data-tip="Remove">${I('x','xs')}</button>${clean ? '<span class="atx-ln" aria-hidden="true"><i></i></span>' : ''}</div>`);
    list.appendChild(it); enter(it, i * 80);
    $('.ib', it).onclick = () => { it.classList.add('leave'); setTimeout(() => it.remove(), 320); };
    const svg = $('.atx-ring', it), ring = $$('circle', it)[1], m = $('.atx-m', it); let p = 0;
    const iv = c.every(70, () => {
      p = Math.min(1, p + .025 + Math.random() * .05); ring.style.strokeDashoffset = 50.3 * (1 - p);
      it.style.setProperty('--dm-p', (p * 100).toFixed(1) + '%'); svg.setAttribute('aria-valuenow', Math.round(p * 100)); const pc = $('.pc', m); if (pc) pc.textContent = Math.round(p * 100) + '%';
      if (p < 1) return;
      clearInterval(iv); it.classList.add('up');
      // reading: the ring gives way to a spinner and the line shimmers, then says what the agent found
      svg.outerHTML = '<span class="atx-rd"><span class="spin"></span></span>'; swap(m, `<span class="shim">${sz} · Reading</span>`, true);
      c.later(REDUCE ? 0 : 900, () => {
        const rd = $('.atx-rd', it); if (rd) rd.outerHTML = `<span class="atx-ok">${clean ? '<span class="atx-okc"><svg viewBox="0 0 16 16" aria-hidden="true"><path pathLength="1" d="M4.6 8.3l2.3 2.3 4.5-4.8"/></svg></span>' : I('ok')}</span>`;
        swap(m, found ? `${sz} · ${found}` : sz); read++;
        if (!clean) { swap(sum, 'The agent can read ' + read + (read > 1 ? ' files' : ' file') + ' now'); return; }
        // Clean: the foot strip opens with a green tick, and from then on only its count rolls
        const w = read > 1 ? 'files' : 'file', rl = $('.atx-roll', sum);
        if (!rl) swap(sum, `<span class="atx-tk">${I('check','xs')}</span><span>The agent can read <span class="atx-roll num"><i>${read}</i></span> <span class="atx-w">${w}</span> now</span>`, true);
        else { rl.innerHTML = `<i class="in">${read}</i>`; $('.atx-w', sum).textContent = w; }
      });
    });
  }
  const samples = () => [['brief.pdf', 2.4e6, '12 pages'],['Pricing.fig', 8.1e6, '6 frames'],['signups.csv', 3.2e5, '1,204 rows']].forEach((f, i) => add(f[0], f[1], i, f[2]));
  $(clean ? '.atx-smp' : '.atx-sample', r).onclick = e => { e.preventDefault(); samples(); };
  $$('.atx-file', r).forEach(inp => { inp.onchange = e => { Array.from(e.target.files).forEach((f, i) => add(f.name, f.size, i)); e.target.value = ''; }; });
  ['dragenter','dragover'].forEach(ev => c.on(drop, ev, e => { e.preventDefault(); drop.classList.add('over'); }));
